css:
.fx-srch{width:min(600px,100%);min-height:380px;display:grid;align-content:start;gap:1em}
.fx-srch h3{font-size:1.5em;text-align:center}.fx-srch .sub{text-align:center;opacity:.6;font-size:.9em;margin-top:-.5em}
.fx-srch .wrap{position:relative;width:88%;margin:.6em auto 0;transition:width calc(.4s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-srch .wrap:focus-within{width:100%}
.fx-srch .bar{display:flex;align-items:center;gap:.7em;padding:.35em .5em .35em 1.1em;border-radius:99px;border:1.5px solid var(--border);background:color-mix(in srgb,var(--surface) 94%,var(--text));transition:border-color .2s,box-shadow .2s}
.fx-srch .wrap:focus-within .bar{border-color:var(--primary);box-shadow:0 0 0 4px color-mix(in srgb,var(--primary) 16%,transparent),0 14px 30px -18px rgba(0,0,0,.4)}
.fx-srch .bar svg{flex:none;width:1.2em;height:1.2em;stroke:currentColor;opacity:.55;fill:none;stroke-width:2;stroke-linecap:round}
.fx-srch .bar input{flex:1;min-width:0;border:0;background:transparent;color:var(--text);font:inherit;padding:.7em 0}
.fx-srch .bar input:focus{outline:none}
.fx-srch .bar kbd{font:600 .72em var(--font-body);padding:.25em .55em;border-radius:6px;border:1px solid var(--border);opacity:.6}
.fx-srch .wrap:focus-within kbd{display:none}
.fx-srch .clr{all:unset;cursor:pointer;display:none;width:2em;height:2em;border-radius:50%;place-items:center;font-size:.85em;background:color-mix(in srgb,var(--text) 10%,transparent)}
.fx-srch .clr.on{display:grid}.fx-srch .clr:focus-visible{outline:2px solid var(--accent)}
.fx-srch .list{position:absolute;top:calc(100% + .5em);left:0;right:0;z-index:2;margin:0;padding:.4em;list-style:none;background:var(--surface);border:1px solid var(--border);border-radius:calc(var(--radius) + 2px);box-shadow:0 24px 40px -20px rgba(0,0,0,.4);opacity:0;visibility:hidden;transform:translateY(-6px);transition:all calc(.2s/var(--speed))}
.fx-srch .list.open{opacity:1;visibility:visible;transform:none}
.fx-srch .list li{display:flex;justify-content:space-between;gap:1em;padding:.65em .8em;border-radius:calc(var(--radius) - 2px);cursor:pointer;font-size:.95em}
.fx-srch .list li small{opacity:.5;font-size:.8em;align-self:center;text-transform:uppercase;letter-spacing:.08em}
.fx-srch .list li[aria-selected=true],.fx-srch .list li:hover{background:color-mix(in srgb,var(--primary) 11%,transparent)}
.fx-srch .list mark{background:color-mix(in srgb,var(--accent) 30%,transparent);color:inherit;border-radius:3px;padding:0 1px}
.fx-srch .none{padding:.9em;opacity:.6;font-size:.9em}
@media(prefers-reduced-motion:reduce){.fx-srch .wrap,.fx-srch .list{transition:none}}

/* touch: :hover mirrored as .is-tap */
.fx-srch .list li.is-tap{background:color-mix(in srgb,var(--primary) 11%,transparent)}

