(function(){var root=document.querySelector('.fx-srch'),inp=root.querySelector('input'),ul=root.querySelector('.list'),clr=root.querySelector('.clr');
var D=[['Choosing a type pairing','Guide'],['Brand identity in three colours','Case study'],['Web typography checklist','Guide'],['Designing quiet interfaces','Journal'],['Brand voice workshop','Service'],['Building a website that lasts','Journal'],['Packaging for small batches','Case study'],['Typeface licensing, explained','Guide'],['Website accessibility audit','Service']];
var cur=-1,shown=[];function esc(s){return s.replace(/[&<>]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]})}
function hl(s,q){if(!q)return esc(s);var i=s.toLowerCase().indexOf(q);return i<0?esc(s):esc(s.slice(0,i))+'<mark>'+esc(s.slice(i,i+q.length))+'</mark>'+esc(s.slice(i+q.length))}
function render(){var q=inp.value.trim().toLowerCase();clr.classList.toggle('on',!!inp.value);shown=D.filter(function(d){return !q||d[0].toLowerCase().indexOf(q)>-1}).slice(0,6);cur=-1;
ul.innerHTML=shown.length?shown.map(function(d,i){return '<li role="option" id="srch-o'+i+'" data-i="'+i+'"><span>'+hl(d[0],q)+'</span><small>'+d[1]+'</small></li>'}).join(''):'<li class="none" role="option" aria-disabled="true">No results for “'+esc(inp.value)+'”</li>';
inp.removeAttribute('aria-activedescendant')}
function open(o){ul.classList.toggle('open',o);inp.setAttribute('aria-expanded',o)}
function sel(i){var o=ul.querySelectorAll('li[data-i]');if(!o.length)return;cur=(i+o.length)%o.length;o.forEach(function(x,k){x.setAttribute('aria-selected',k===cur)});inp.setAttribute('aria-activedescendant',o[cur].id)}
function pick(i){inp.value=shown[i][0];open(false);render();ul.classList.remove('open');clr.classList.add('on')}
inp.addEventListener('focus',function(){render();open(true)});inp.addEventListener('input',function(){render();open(true)});
inp.addEventListener('keydown',function(e){if(e.key==='ArrowDown'){e.preventDefault();open(true);sel(cur+1)}else if(e.key==='ArrowUp'){e.preventDefault();sel(cur-1)}else if(e.key==='Enter'&&cur>-1){e.preventDefault();pick(cur)}else if(e.key==='Escape'){if(ul.classList.contains('open'))open(false);else{inp.value='';render()}}});
ul.addEventListener('mousedown',function(e){var li=e.target.closest('li[data-i]');if(li){e.preventDefault();pick(+li.dataset.i)}});
clr.addEventListener('click',function(){inp.value='';render();inp.focus()});
root.addEventListener('focusout',function(e){if(!root.querySelector('.wrap').contains(e.relatedTarget))open(false)});
document.addEventListener('keydown',function(e){if(e.key==='/'&&document.activeElement!==inp&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)){e.preventDefault();inp.focus()}});render()})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
